export interface ConnectorConfig {
  stripeSecretKey: string
  fetch?: typeof fetch
}

export interface HubSpotContactPayload {
  properties: {
    email: string
    firstname: string
    lastname: string
    lifecyclestage: string
  }
  objectId: string
  subscriptionType: string
  propertyName: string
  propertyValue: string
}

export interface HandleResult {
  stripeCustomerId: string
}

export async function handle(
  payload: HubSpotContactPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.properties?.email) {
    throw new Error('Missing required field: properties.email')
  }
  if (!payload.properties?.firstname) {
    throw new Error('Missing required field: properties.firstname')
  }
  if (!payload.properties?.lastname) {
    throw new Error('Missing required field: properties.lastname')
  }
  if (payload.properties?.lifecyclestage !== 'customer') {
    throw new Error('Lifecycle stage is not "customer", skipping')
  }

  const email = payload.properties.email
  const name = `${payload.properties.firstname} ${payload.properties.lastname}`.trim()

  const body = JSON.stringify({ email, name })

  const response = await fetchImpl('https://api.stripe.com/v1/customers', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.stripeSecretKey}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: new URLSearchParams({ email, name }).toString(),
  })

  if (!response.ok) {
    throw new Error(`Stripe API error: ${response.status} ${response.statusText} at POST https://api.stripe.com/v1/customers`)
  }

  const data = (await response.json()) as { id: string }
  return { stripeCustomerId: data.id }
}

